"use client";

import { FormEvent, ReactNode, useEffect, useState } from "react";
import Link from "next/link";
import { useRouter, useSearchParams } from "next/navigation";
import { ArrowRight, Bell, CheckCircle2, Clock3, Download, FilePenLine, FileText, FolderKanban, Headphones, LockKeyhole, LogOut, MailCheck, MessageCircle, Plus, ShieldCheck, UserRound, X } from "lucide-react";
import { CatalogueHeader } from "@/components/catalogue-header";
import { customerFetch, getCustomerSession, requestCustomerPasswordReset, signInCustomer, signOutCustomer, signUpCustomer, updateCustomerPassword } from "@/lib/auth/customer-client";
import { whatsappContactHref } from "@/lib/contact";
import { readQuoteLeadDraft } from "@/lib/quotation-draft";
import { getCustomerSupabaseBrowserClient } from "@/lib/supabase/client";
import { previewEntries } from "@/components/admin-change-confirmation-guard";
import { IndiaLocationFields } from "@/components/india-location-fields";
import type { CustomerAccount, CustomerRecord, CustomerRevisionRequest, DocumentRecord, EnquiryRecord, ProjectRecord, QuotationRecord } from "@/lib/db/types";
import { quotationStatusLabel } from "@/lib/quotations/status";

type PortalResponse = { ok?: boolean; message?: string; account?: CustomerAccount; customer?: CustomerRecord; enquiries?: EnquiryRecord[]; quotations?: QuotationRecord[]; projects?: ProjectRecord[]; documents?: DocumentRecord[]; revisionRequests?: CustomerRevisionRequest[]; access?: "allowed" | "restricted" };

function intentUrl(path: string, intent?: string | null) { return intent ? `${path}?intent=${encodeURIComponent(intent)}` : path; }
function errorMessage(data: PortalResponse, fallback: string) { return data.message || fallback; }
function statusLabel(status?: CustomerAccount["status"]) { return (status || "pending_email_verification").replaceAll("_", " "); }
function enquiryStatus(status: EnquiryRecord["status"]) { return ({ new: "Received", contacted: "Under Review", qualified: "Under Review", requirement_received: "Received", quotation_required: "Under Review", quoted: "Quotation Prepared", quotation_sent: "Quotation Created", converted: "Quotation Created", won: "Closed", lost: "Closed", not_relevant: "Closed", closed: "Closed" } as Partial<Record<EnquiryRecord["status"], string>>)[status] || "Under Review"; }
function quotationStatus(status: QuotationRecord["status"]) { return quotationStatusLabel(status); }
function money(value: number) { return `₹${value.toLocaleString("en-IN", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`; }

async function loadPortal(): Promise<PortalResponse> {
  const response = await customerFetch("/api/customer-auth/me", { cache: "no-store" });
  const data = await response.json() as PortalResponse;
  if (!response.ok) throw new Error(errorMessage(data, "Could not load your account."));
  return data;
}

async function attachIntent(intent?: string | null) {
  if (!intent) return;
  const response = await customerFetch("/api/customer-auth/continue", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ intent }) });
  const data = await response.json() as PortalResponse;
  if (!response.ok) throw new Error(errorMessage(data, "Could not restore your enquiry."));
}

async function continueByStatus(router: ReturnType<typeof useRouter>, intent?: string | null) {
  const portal = await loadPortal();
  await attachIntent(intent);
  // A normal sign-in always opens the customer dashboard. Only the explicit
  // continuation token created after an enquiry may resume the quotation flow.
  if (portal.account?.status === "active") {
    router.replace(intent ? "/generate-quotation?from=enquiry" : "/account");
    return;
  }
  router.replace(intentUrl("/account/pending-approval", intent));
}

function AccountFrame({ children }: { children: ReactNode }) {
  return <><CatalogueHeader /><main className="customer-portal"><div className="customer-portal-shell">{children}</div></main></>;
}

function PortalNav({ active = "overview", restricted = false }: { active?: "overview" | "enquiries" | "quotations" | "projects" | "documents" | "profile" | "support"; restricted?: boolean }) {
  const router = useRouter();
  const links = [{ id: "overview", label: "Dashboard", href: "/account" }, { id: "enquiries", label: "My enquiries", href: "/account/enquiries" }, { id: "quotations", label: "My quotations", href: "/account/quotations", activeOnly: true }, { id: "projects", label: "My projects", href: "/account/projects", activeOnly: true }, { id: "documents", label: "Documents", href: "/account/documents", activeOnly: true }, { id: "profile", label: "Profile", href: "/account/profile" }, { id: "support", label: "Support", href: "/account/support" }];
  return <nav className="customer-portal-nav" aria-label="Customer portal navigation">{links.filter((link) => !restricted || !link.activeOnly).map((link) => <Link className={active === link.id ? "active" : ""} href={link.href} key={link.id}>{link.label}</Link>)}{!restricted && <Link className="customer-nav-generate" href="/generate-quotation">Generate quotation <ArrowRight size={14} /></Link>}<button onClick={async () => { await signOutCustomer(); router.push("/"); }}><LogOut size={15} /> Sign out</button></nav>;
}

function AuthCard({ children }: { children: ReactNode }) { return <AccountFrame><section className="customer-auth-card">{children}</section></AccountFrame>; }

export function AccountContinuePage() {
  const router = useRouter(); const params = useSearchParams(); const intent = params.get("intent") || readQuoteLeadDraft()?.continuationToken || "";
  const draft = readQuoteLeadDraft(); const [message, setMessage] = useState("Checking your account…");
  useEffect(() => { let alive = true; (async () => { const session = await getCustomerSession(); if (!alive) return; if (!session) { setMessage(""); return; } try { await continueByStatus(router, intent); } catch (error) { if (alive) setMessage(error instanceof Error ? error.message : "Could not restore your enquiry."); } })(); return () => { alive = false; }; }, [intent, router]);
  return <AuthCard><div className="customer-kicker"><LockKeyhole size={15} /> SECURE QUOTATION ACCESS</div><h1>Continue your enquiry</h1><p>{draft?.enquiryNumber ? <>Enquiry <strong>{draft.enquiryNumber}</strong> has been saved.</> : "Your enquiry is saved before sign-in."} Only RAC-approved customers can generate commercial quotations.</p>{message && <p className="customer-note">{message}</p>}<div className="customer-auth-actions"><Link className="customer-primary" href={intentUrl("/account/sign-in", intent)}>Sign in <ArrowRight size={17} /></Link><Link className="customer-secondary" href={intentUrl("/account/sign-up", intent)}>Create an account</Link></div><p className="customer-small">New accounts are reviewed by RAC Admin after email verification. Your enquiry remains safely recorded even if you return later.</p></AuthCard>;
}

export function CustomerSignInPage() {
  const router = useRouter(); const params = useSearchParams(); const intent = params.get("intent") || ""; const draft = readQuoteLeadDraft();
  const [busy, setBusy] = useState(false); const [error, setError] = useState("");
  const submit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); setBusy(true); setError(""); try { await signInCustomer(String(data.get("identity") || ""), String(data.get("password") || "")); await continueByStatus(router, intent); } catch (issue) { setError(issue instanceof Error ? issue.message : "Could not sign in."); } finally { setBusy(false); } };
  return <AuthCard><div className="customer-kicker"><UserRound size={15} /> CUSTOMER SIGN IN</div><h1>Welcome back</h1><p>Sign in with the email address used when you registered. Your registered email address is your User ID.</p><form className="customer-form" onSubmit={submit}><label>Email address<input required name="identity" type="email" defaultValue={draft?.email || ""} autoComplete="username" /></label><p className="customer-auth-help customer-inline-help"><strong>Forgot your User ID?</strong><span>Your User ID is your registered email address. If you cannot remember it, contact RAC from your registered mobile number.</span></p><label>Password<input required name="password" type="password" minLength={8} autoComplete="current-password" /></label><p className="customer-small customer-password-help"><Link href={intentUrl("/account/forgot-password", intent)}>Forgot password?</Link></p>{error && <p className="customer-error">{error}</p>}<button className="customer-primary" disabled={busy}>{busy ? "Signing in…" : "Sign in securely"}<ArrowRight size={17} /></button></form><p className="customer-small">New to RAC? <Link href={intentUrl("/account/sign-up", intent)}>Create an account</Link></p></AuthCard>;
}

export function CustomerForgotPasswordPage() {
  const params = useSearchParams(); const intent = params.get("intent") || "";
  const [busy, setBusy] = useState(false); const [error, setError] = useState(""); const [message, setMessage] = useState("");
  const submit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); const data = new FormData(event.currentTarget); setBusy(true); setError(""); setMessage("");
    try {
      await requestCustomerPasswordReset(String(data.get("email") || ""), intent);
      setMessage("If an RAC account is registered with this email, we have sent a secure password-reset link. Please check your inbox and spam folder.");
    } catch (issue) { setError(issue instanceof Error ? issue.message : "Could not send the password-reset email."); } finally { setBusy(false); }
  };
  return <AuthCard><div className="customer-kicker"><MailCheck size={15} /> PASSWORD RECOVERY</div><h1>Reset your password</h1><p>Enter the email address used when you registered. We will send a secure link to choose a new password.</p><form className="customer-form" onSubmit={submit}><label>Registered email address<input required name="email" type="email" autoComplete="email" placeholder="you@company.com" /></label>{error && <p className="customer-error">{error}</p>}{message && <p className="customer-note">{message}</p>}<button className="customer-primary" disabled={busy}>{busy ? "Sending reset link…" : "Send reset link"}<ArrowRight size={17} /></button></form><section className="customer-auth-help"><strong>Your User ID is your registered email address.</strong><span>There is no separate username. If you cannot remember that email, contact RAC from your registered mobile number so we can verify your identity before helping.</span></section><p className="customer-small"><Link href={intentUrl("/account/sign-in", intent)}>Back to sign in</Link></p></AuthCard>;
}

export function CustomerResetPasswordPage() {
  const params = useSearchParams(); const intent = params.get("intent") || "";
  const [checking, setChecking] = useState(() => Boolean(getCustomerSupabaseBrowserClient())); const [ready, setReady] = useState(false); const [busy, setBusy] = useState(false); const [error, setError] = useState(""); const [complete, setComplete] = useState(false);
  useEffect(() => {
    const client = getCustomerSupabaseBrowserClient();
    if (!client) return;
    let alive = true;
    const sync = async () => { const { data: { session } } = await client.auth.getSession(); if (alive) { setReady(Boolean(session?.user)); setChecking(false); } };
    const { data: { subscription } } = client.auth.onAuthStateChange((_event, session) => { if (alive) { setReady(Boolean(session?.user)); setChecking(false); } });
    void sync();
    return () => { alive = false; subscription.unsubscribe(); };
  }, []);
  const submit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); const data = new FormData(event.currentTarget); const password = String(data.get("password") || "");
    if (password !== String(data.get("confirmPassword") || "")) { setError("Passwords do not match."); return; }
    setBusy(true); setError("");
    try { await updateCustomerPassword(password); setComplete(true); } catch (issue) { setError(issue instanceof Error ? issue.message : "Could not update your password."); } finally { setBusy(false); }
  };
  if (checking) return <AuthCard><div className="customer-kicker"><LockKeyhole size={15} /> PASSWORD RECOVERY</div><h1>Checking your reset link</h1><p>Please wait while we verify your secure password-reset link.</p></AuthCard>;
  if (complete) return <AuthCard><div className="customer-kicker"><CheckCircle2 size={15} /> PASSWORD UPDATED</div><h1>Your password has been updated</h1><p>Sign in with your registered email address and new password.</p><div className="customer-auth-actions"><Link className="customer-primary" href={intentUrl("/account/sign-in", intent)}>Sign in</Link></div></AuthCard>;
  if (!ready) return <AuthCard><div className="customer-kicker"><LockKeyhole size={15} /> PASSWORD RECOVERY</div><h1>Reset link unavailable</h1><p>This password-reset link may have expired or already been used. Request a new link and open the latest email in this browser.</p><div className="customer-auth-actions"><Link className="customer-primary" href={intentUrl("/account/forgot-password", intent)}>Request new link</Link><Link className="customer-secondary" href={intentUrl("/account/sign-in", intent)}>Back to sign in</Link></div></AuthCard>;
  return <AuthCard><div className="customer-kicker"><LockKeyhole size={15} /> CHOOSE NEW PASSWORD</div><h1>Set a new password</h1><p>Choose a secure password with at least eight characters.</p><form className="customer-form" onSubmit={submit}><label>New password<input required name="password" type="password" minLength={8} autoComplete="new-password" /></label><label>Confirm new password<input required name="confirmPassword" type="password" minLength={8} autoComplete="new-password" /></label>{error && <p className="customer-error">{error}</p>}<button className="customer-primary" disabled={busy}>{busy ? "Updating password…" : "Update password"}<ArrowRight size={17} /></button></form></AuthCard>;
}

export function CustomerSignUpPage() {
  const router = useRouter(); const params = useSearchParams(); const intent = params.get("intent") || ""; const draft = readQuoteLeadDraft();
  const [busy, setBusy] = useState(false); const [error, setError] = useState("");
  const submit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); const password = String(data.get("password") || ""); if (password !== String(data.get("confirmPassword") || "")) { setError("Passwords do not match."); return; } setBusy(true); setError(""); try { const result = await signUpCustomer({ fullName: String(data.get("fullName") || ""), companyName: String(data.get("companyName") || ""), email: String(data.get("email") || ""), mobile: String(data.get("mobile") || ""), gstin: String(data.get("gstin") || ""), customerType: String(data.get("customerType") || "end_user") as CustomerAccount["customerType"], password, intent }); if (result.requiresEmailVerification) { router.replace(intentUrl("/account/pending-approval", intent)); return; } await continueByStatus(router, intent); } catch (issue) { setError(issue instanceof Error ? issue.message : "Could not create your account."); } finally { setBusy(false); } };
  return <AuthCard><div className="customer-kicker"><ShieldCheck size={15} /> CUSTOMER REGISTRATION</div><h1>Create your account</h1><p>Your email address will be your User ID. After registration, confirm the email link once; then RAC Admin will review the account.</p><form className="customer-form customer-form-grid" onSubmit={submit}><label>Full name<input required name="fullName" defaultValue={draft?.name || ""} autoComplete="name" /></label><label>Company name<input required name="companyName" defaultValue={draft?.company || ""} autoComplete="organization" /></label><label>Email<input required name="email" type="email" defaultValue={draft?.email || ""} autoComplete="email" /></label><label>Mobile<input required name="mobile" defaultValue={draft?.mobile || ""} autoComplete="tel" /></label><label>Customer type<select name="customerType" defaultValue={draft?.customerType || "end_user"}><option value="end_user">End user</option><option value="contractor">Contractor</option><option value="consultant">Consultant</option><option value="dealer">Dealer</option><option value="other">Other</option></select></label><label>GSTIN <small>Optional</small><input name="gstin" autoCapitalize="characters" /></label><label>Password<input required name="password" type="password" minLength={8} autoComplete="new-password" /></label><label>Confirm password<input required name="confirmPassword" type="password" minLength={8} autoComplete="new-password" /></label>{error && <p className="customer-error customer-full">{error}</p>}<button className="customer-primary customer-full" disabled={busy}>{busy ? "Creating account…" : "Create account"}<ArrowRight size={17} /></button></form><p className="customer-small">Already registered? <Link href={intentUrl("/account/sign-in", intent)}>Sign in</Link> · <Link href={intentUrl("/account/forgot-password", intent)}>Forgot password?</Link></p></AuthCard>;
}

export function AccountPendingPage() {
  const router = useRouter(); const [portal, setPortal] = useState<PortalResponse>(); const [error, setError] = useState("");
  useEffect(() => { loadPortal().then((value) => { if (value.account?.status === "active") router.replace("/account"); else setPortal(value); }).catch((issue) => setError(issue instanceof Error ? issue.message : "Please sign in to view your account status.")); }, [router]);
  const account = portal?.account; const draft = readQuoteLeadDraft();
  return <AuthCard><div className="customer-kicker"><Clock3 size={15} /> ACCOUNT VERIFICATION</div><h1>{account?.status === "pending_email_verification" ? "Verify your email" : account?.status === "rejected" ? "Account access is restricted" : account?.status === "suspended" ? "Account access is paused" : "Your account is under verification"}</h1><p>{account?.status === "pending_email_verification" ? "Please use the verification link sent to your email. Once verified, RAC Admin can review your registration." : account?.status === "rejected" || account?.status === "suspended" ? "Quotation generation is not currently available. Contact RAC if you need help." : <>Your enquiry{draft?.enquiryNumber ? <> <strong>{draft.enquiryNumber}</strong></> : ""} has been received. Once RAC approves your account, you can generate quotations and access history.</>}</p>{error && <p className="customer-error">{error}</p>}<div className="customer-auth-actions"><Link className="customer-secondary" href="/account/enquiries">View my enquiry</Link><a className="customer-primary" target="_blank" rel="noreferrer" href={whatsappContactHref("my RAC Insutech account approval")}>Contact RAC <MessageCircle size={17} /></a></div><button className="customer-text-button" onClick={async () => { await signOutCustomer(); router.push("/"); }}>Sign out</button></AuthCard>;
}

function useActivePortal(options: { allowRestricted?: boolean } = {}) {
  const router = useRouter(); const [portal, setPortal] = useState<PortalResponse>(); const [error, setError] = useState("");
  useEffect(() => { loadPortal().then((value) => { const status = value.account?.status; if (!value.account) { router.replace("/account/sign-in"); return; } if (!options.allowRestricted && (status !== "active" || value.access !== "allowed")) { router.replace("/account/pending-approval"); return; } if (status === "rejected" || status === "archived") { router.replace("/account/pending-approval"); return; } setPortal(value); }).catch((issue) => { setError(issue instanceof Error ? issue.message : "Please sign in to continue."); }); }, [options.allowRestricted, router]);
  return { portal, error };
}

function AccountLoading({ error }: { error: string }) { return <AccountFrame><section className="customer-account-card"><p>{error || "Loading your account…"}</p>{error && <Link className="customer-primary" href="/account/sign-in">Sign in</Link>}</section></AccountFrame>; }

export function CustomerAccountHome() {
  const { portal, error } = useActivePortal(); if (!portal) return <AccountLoading error={error} />; const { account, customer, enquiries = [], quotations = [] } = portal;
  const projects = portal.projects || []; const activeQuotes = quotations.filter((quote) => ["generated", "sent", "viewed", "revised"].includes(quote.status)); const pending = quotations.filter((quote) => quote.status === "revision_requested").length + (portal.revisionRequests || []).filter((item) => item.status === "open").length;
  return <AccountFrame><PortalNav /><section className="customer-account-hero"><div><p className="customer-kicker"><CheckCircle2 size={15} /> VERIFIED CUSTOMER</p><h1>Welcome, {account?.fullName}</h1><p>{customer?.company || account?.companyName || "Your RAC Insutech customer account"}. Manage your enquiries, projects and quotations from one place.</p></div><div className="customer-hero-actions"><Link className="customer-primary" href="/generate-quotation">Generate quotation <ArrowRight size={17} /></Link><Link className="customer-secondary" href="/?quote=1">Submit enquiry</Link></div></section><section className="customer-stat-grid customer-stat-grid-five"><article><strong>{enquiries.length}</strong><span>My enquiries</span></article><article><strong>{quotations.length}</strong><span>My quotations</span></article><article><strong>{activeQuotes.length}</strong><span>Active quotations</span></article><article><strong>{projects.length}</strong><span>Projects</span></article><article><strong>{pending}</strong><span>Pending actions</span></article></section>{pending > 0 && <section className="customer-attention"><Bell size={18} /><div><strong>Requires your attention</strong><p>{pending} quotation update{pending === 1 ? " is" : "s are"} awaiting the next RAC action.</p></div><Link href="/account/quotations">View quotations <ArrowRight size={15} /></Link></section>}<section className="customer-dashboard-grid"><section className="customer-account-card"><div className="customer-card-title"><div><p className="customer-kicker"><FileText size={14} /> RECENT QUOTATIONS</p><h2>Commercial activity</h2></div><Link href="/account/quotations">View all</Link></div>{quotations.length ? <div className="customer-list">{quotations.slice(0, 4).map((quote) => <article key={quote.id}><div><strong>{quote.quoteNumber}</strong><span>{money(quote.total)} · {quote.customer.projectName || "Project to be confirmed"}</span></div><Link className="customer-row-link" href={`/account/quotations/${quote.id}`}>{quotationStatus(quote.status)} <ArrowRight size={14} /></Link></article>)}</div> : <div className="customer-empty-state"><FileText size={25} /><p>You haven&apos;t generated any quotations yet.</p><Link className="customer-primary" href="/generate-quotation">Generate your first quotation</Link></div>}</section><section className="customer-account-card"><div className="customer-card-title"><div><p className="customer-kicker"><Clock3 size={14} /> RECENT ENQUIRIES</p><h2>Requirements</h2></div><Link href="/account/enquiries">View all</Link></div>{enquiries.length ? <div className="customer-list">{enquiries.slice(0, 4).map((enquiry) => <article key={enquiry.id}><div><strong>{enquiry.enquiryNumber}</strong><span>{enquiry.product || "General insulation requirement"}</span></div><Link className="customer-row-link" href={`/account/enquiries/${enquiry.id}`}>{enquiryStatus(enquiry.status)} <ArrowRight size={14} /></Link></article>)}</div> : <div className="customer-empty-state"><MessageCircle size={25} /><p>No enquiries are linked to this account yet.</p><Link className="customer-secondary" href="/?quote=1">Submit enquiry</Link></div>}</section></section></AccountFrame>;
}

export function CustomerEnquiriesPage() { const { portal, error } = useActivePortal({ allowRestricted: true }); if (!portal) return <AccountLoading error={error} />; const restricted = portal.account?.status !== "active"; return <AccountFrame><PortalNav active="enquiries" restricted={restricted} /><section className="customer-account-card"><div className="customer-card-title"><div><p className="customer-kicker"><FileText size={14} /> ENQUIRY HISTORY</p><h1>My enquiries</h1></div>{!restricted && <Link className="customer-primary" href="/?quote=1">New enquiry <ArrowRight size={16} /></Link>}</div><div className="customer-list customer-list-expanded">{portal.enquiries?.length ? portal.enquiries.map((enquiry) => <article key={enquiry.id}><div><strong>{enquiry.enquiryNumber}</strong><span>{enquiry.product || "General insulation requirement"} · {enquiry.projectName || "No project name"}</span><small>{new Date(enquiry.createdAt).toLocaleDateString("en-IN")}</small></div><div className="customer-list-actions"><em>{enquiryStatus(enquiry.status)}</em><Link href={`/account/enquiries/${enquiry.id}`}>View <ArrowRight size={14} /></Link></div></article>) : <div className="customer-empty-state"><FileText size={26} /><p>No enquiries yet.</p>{!restricted && <Link className="customer-primary" href="/?quote=1">Submit enquiry</Link>}</div>}</div></section></AccountFrame>; }

export function CustomerQuotationsPage() { const { portal, error } = useActivePortal({ allowRestricted: true }); const [filter, setFilter] = useState("all"); if (!portal) return <AccountLoading error={error} />; const restricted = portal.account?.status !== "active"; const quotes = (portal.quotations || []).filter((quote) => filter === "all" || (filter === "active" ? ["generated", "sent", "viewed", "revised"].includes(quote.status) : quote.status === filter)); return <AccountFrame><PortalNav active="quotations" restricted={restricted} /><section className="customer-account-card"><div className="customer-card-title"><div><p className="customer-kicker"><FileText size={14} /> QUOTATION HISTORY</p><h1>My quotations</h1></div>{!restricted && <Link className="customer-primary" href="/generate-quotation">Generate quotation <ArrowRight size={16} /></Link>}</div><div className="customer-filter-row">{[["all", "All"], ["active", "Active"], ["expired", "Expired"], ["accepted", "Accepted"], ["revised", "Revised"]].map(([value, label]) => <button className={filter === value ? "active" : ""} onClick={() => setFilter(value)} key={value}>{label}</button>)}</div><div className="customer-list customer-list-expanded">{quotes.length ? quotes.map((quote) => <article key={quote.id}><div><strong>{quote.quoteNumber}</strong><span>{quote.customer.projectName || "Project to be confirmed"} · {money(quote.total)}</span><small>Valid until {quote.validUntil ? new Date(quote.validUntil).toLocaleDateString("en-IN") : "—"}</small></div><div className="customer-list-actions"><em>{quotationStatus(quote.status)}</em><Link href={`/account/quotations/${quote.id}`}>Open <ArrowRight size={14} /></Link></div></article>) : <div className="customer-empty-state"><FileText size={26} /><p>You haven&apos;t generated any quotations yet.</p>{!restricted && <Link className="customer-primary" href="/generate-quotation">Generate your first quotation</Link>}</div>}</div></section></AccountFrame>; }

export function CustomerProfilePage() {
  const { portal, error } = useActivePortal({ allowRestricted: true }); const [editing, setEditing] = useState(false); const [busy, setBusy] = useState(false); const [message, setMessage] = useState(""); const [pendingUpdate, setPendingUpdate] = useState<Record<string, unknown> | null>(null);
  if (!portal) return <AccountLoading error={error} />;
  const { account, customer } = portal; const restricted = account?.status !== "active";
  const save = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const fields = new FormData(event.currentTarget); setMessage(""); setPendingUpdate({ fullName: fields.get("fullName"), mobile: fields.get("mobile"), billingAddress: fields.get("billingAddress"), shippingAddress: fields.get("shippingAddress"), city: fields.get("city"), state: fields.get("state"), pinCode: fields.get("pinCode") }); };
  const confirmUpdate = async () => { if (!pendingUpdate) return; setBusy(true); setMessage(""); try { const response = await customerFetch("/api/customer-auth/profile", { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify(pendingUpdate) }); const data = await response.json() as PortalResponse; if (!response.ok || !data.account) throw new Error(data.message || "Could not update your profile."); setPendingUpdate(null); setMessage("Profile updated. Your enquiry and quotation history remains unchanged."); setEditing(false); window.setTimeout(() => window.location.reload(), 450); } catch (issue) { setMessage(issue instanceof Error ? issue.message : "Could not update your profile."); } finally { setBusy(false); } };
  return <AccountFrame><PortalNav active="profile" restricted={restricted} /><section className="customer-account-card"><div className="customer-card-title"><div><p className="customer-kicker"><UserRound size={14} /> ACCOUNT PROFILE</p><h1>Company and contact details</h1></div>{!editing && !restricted && <button className="customer-secondary" onClick={() => setEditing(true)}>Edit safe details</button>}</div>{editing ? <form className="customer-form customer-form-grid" onSubmit={save}><label>Contact name<input required name="fullName" defaultValue={account?.fullName} /></label><label>Company<input value={customer?.company || account?.companyName || ""} readOnly aria-readonly="true" /></label><label>Verified email<input value={account?.email} readOnly aria-readonly="true" /></label><label>Mobile<input required name="mobile" defaultValue={account?.mobile} /></label><label>GSTIN<input value={customer?.gstin || account?.gstin || ""} readOnly aria-readonly="true" /></label><label>Customer type<input value={(account?.customerType || "other").replaceAll("_", " ")} readOnly aria-readonly="true" /></label><IndiaLocationFields defaultValue={{ state: customer?.state, city: customer?.city, pinCode: customer?.pinCode }} /><label className="customer-full">Billing address<textarea name="billingAddress" defaultValue={customer?.billingAddress} rows={3} /></label><label className="customer-full">Shipping address<textarea name="shippingAddress" defaultValue={customer?.shippingAddress} rows={3} /></label>{message && <p className="customer-error customer-full">{message}</p>}<div className="customer-auth-actions customer-full"><button type="button" className="customer-secondary" onClick={() => setEditing(false)}>Cancel</button><button className="customer-primary" disabled={busy}>{busy ? "Saving…" : "Review changes"}<ArrowRight size={16} /></button></div></form> : <><div className="customer-profile-grid"><p><span>Contact name</span><strong>{account?.fullName}</strong></p><p><span>Company</span><strong>{customer?.company || account?.companyName || "—"}</strong></p><p><span>Verified email</span><strong>{account?.email}</strong></p><p><span>Mobile</span><strong>{account?.mobile}</strong></p><p><span>GSTIN</span><strong>{customer?.gstin || account?.gstin || "Not provided"}</strong></p><p><span>Customer type</span><strong>{(account?.customerType || "other").replaceAll("_", " ")}</strong></p></div>{message && <p className="customer-note">{message}</p>}{restricted && <p className="customer-note">Your account is awaiting verification or has restricted access. Profile updates are paused; contact RAC if any details need changing.</p>}<p className="customer-small">Company name, GSTIN and primary email are protected commercial identity fields. Contact RAC to request a change; historical quotations remain unchanged.</p></>}</section>{pendingUpdate && <div className="admin-change-confirm-backdrop" role="presentation" onMouseDown={() => setPendingUpdate(null)}><section className="admin-change-confirm" role="dialog" aria-modal="true" aria-labelledby="customer-profile-confirm-title" onMouseDown={(event) => event.stopPropagation()}><header><span className="admin-change-confirm-icon"><FilePenLine size={20} /></span><button type="button" onClick={() => setPendingUpdate(null)} aria-label="Cancel profile update"><X size={18} /></button></header><div className="admin-change-confirm-copy"><p>PROFILE CHANGE PREVIEW</p><h2 id="customer-profile-confirm-title">Review profile changes</h2><span>Check the proposed details before they are saved to your RAC customer profile.</span></div><section className="admin-change-preview"><h3>Proposed values</h3><dl>{previewEntries(pendingUpdate).map((item) => <div key={`${item.label}-${item.value}`}><dt>{item.label}</dt><dd>{item.value}</dd></div>)}</dl></section><footer><button type="button" className="admin-drawer-secondary" onClick={() => setPendingUpdate(null)}>Cancel</button><button type="button" className="admin-os-primary" onClick={() => void confirmUpdate()} disabled={busy}><CheckCircle2 size={15} />{busy ? "Saving…" : "Confirm changes"}</button></footer></section></div>}</AccountFrame>;
}

type DetailResponse = PortalResponse & { enquiry?: EnquiryRecord; quotation?: QuotationRecord; project?: ProjectRecord; linked?: { enquiries: number; quotations: number }; displayStatus?: string };
function usePortalDetail(path: string) {
  const [data, setData] = useState<DetailResponse>(); const [error, setError] = useState("");
  useEffect(() => { let current = true; customerFetch(path, { cache: "no-store" }).then(async (response) => { const result = await response.json() as DetailResponse; if (!response.ok) throw new Error(result.message || "Could not load this record."); if (current) setData(result); }).catch((issue) => { if (current) setError(issue instanceof Error ? issue.message : "Could not load this record."); }); return () => { current = false; }; }, [path]);
  return { data, error };
}
function DetailLoading({ error }: { error: string }) { return <AccountFrame><section className="customer-account-card customer-detail-loading"><p>{error || "Loading your RAC record…"}</p>{error && <Link className="customer-secondary" href="/account">Back to dashboard</Link>}</section></AccountFrame>; }
function DetailFields({ values }: { values: Array<[string, string | undefined]> }) { return <dl className="customer-detail-fields">{values.map(([label, value]) => <div key={label}><dt>{label}</dt><dd>{value || "—"}</dd></div>)}</dl>; }
function CustomerBuiltUpCommercialCells({ quotationItem }: { quotationItem: QuotationRecord["items"][number] }) {
  const layers = quotationItem.customBuiltUp?.layers || [];
  return <><span className="customer-built-up-commercial">{layers.map((layer) => <span key={layer.layerNumber}><small>Layer {layer.layerNumber}</small>{layer.quotedAreaM2.toFixed(2)} m²</span>)}</span><span className="customer-built-up-commercial">{layers.map((layer) => <span key={layer.layerNumber}><small>Layer {layer.layerNumber}</small>{money(layer.rate)}<small>per m²</small></span>)}</span><strong className="customer-built-up-commercial customer-built-up-amounts">{layers.map((layer) => <span key={layer.layerNumber}><small>Layer {layer.layerNumber}</small>{money(layer.amount)}</span>)}</strong></>;
}

export function CustomerEnquiryDetailPage({ id }: { id: string }) {
  const { portal, error: accessError } = useActivePortal({ allowRestricted: true }); const { data, error } = usePortalDetail(`/api/customer-portal/enquiries/${id}`);
  if (!portal || !data?.enquiry) return <DetailLoading error={accessError || error} />; const enquiry = data.enquiry; const restricted = portal.account?.status !== "active";
  return <AccountFrame><PortalNav active="enquiries" restricted={restricted} /><section className="customer-account-card customer-detail-card"><div className="customer-card-title"><div><p className="customer-kicker"><FileText size={14} /> ENQUIRY DETAIL</p><h1>{enquiry.enquiryNumber}</h1><span>{enquiryStatus(enquiry.status)} · submitted {new Date(enquiry.createdAt).toLocaleDateString("en-IN")}</span></div><Link className="customer-secondary" href="/account/enquiries">Back to enquiries</Link></div><DetailFields values={[["Project", enquiry.projectName], ["Project location", enquiry.projectLocation], ["Product / material", enquiry.product], ["Application", enquiry.application], ["Quantity", enquiry.quantity], ["Thickness / size", enquiry.thickness], ["Brand preference", enquiry.brand], ["Delivery requirement", enquiry.deliveryPreference]]} /><section className="customer-detail-note"><strong>Requirement notes</strong><p>{enquiry.message || "No additional requirement notes were supplied."}</p></section>{enquiry.attachment && <section className="customer-detail-note"><strong>Attachment</strong><p>{enquiry.attachment.name} · {(enquiry.attachment.size / 1024 / 1024).toFixed(1)} MB</p></section>}{enquiry.status === "quotation_sent" && <section className="customer-detail-note"><strong>Quotation prepared</strong><p>Your RAC quotation is available in My quotations.</p><Link className="customer-secondary" href="/account/quotations">View quotations</Link></section>}</section></AccountFrame>;
}

export function CustomerQuotationDetailPage({ id }: { id: string }) {
  const { portal, error: accessError } = useActivePortal({ allowRestricted: true }); const { data, error } = usePortalDetail(`/api/customer-portal/quotations/${id}`); const [revisionOpen, setRevisionOpen] = useState(false); const [message, setMessage] = useState(""); const [busy, setBusy] = useState(false);
  if (!portal || !data?.quotation) return <DetailLoading error={accessError || error} />; const quote = data.quotation; const restricted = portal.account?.status !== "active";
  const download = async () => { setMessage(""); try { const response = await customerFetch(`/api/quotations/${quote.id}/pdf`); if (!response.ok) { const body = await response.text(); throw new Error(body || "Could not download the quotation."); } const blob = await response.blob(); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = `${quote.quoteNumber}.pdf`; link.click(); URL.revokeObjectURL(url); } catch (issue) { setMessage(issue instanceof Error ? issue.message : "Could not download the quotation."); } };
  const requestRevision = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const fields = new FormData(event.currentTarget); setBusy(true); setMessage(""); try { const response = await customerFetch(`/api/customer-portal/quotations/${quote.id}/revision-request`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ reason: fields.get("reason"), requiredChange: fields.get("requiredChange"), quantityChange: fields.get("quantityChange"), productChange: fields.get("productChange"), deliveryChange: fields.get("deliveryChange"), additionalNotes: fields.get("additionalNotes") }) }); const result = await response.json() as PortalResponse; if (!response.ok) throw new Error(result.message || "Could not submit the revision request."); setRevisionOpen(false); setMessage("Your revision request has been sent to RAC. The existing quotation remains unchanged."); } catch (issue) { setMessage(issue instanceof Error ? issue.message : "Could not submit the revision request."); } finally { setBusy(false); } };
  return <AccountFrame><PortalNav active="quotations" restricted={restricted} /><section className="customer-account-card customer-detail-card"><div className="customer-card-title"><div><p className="customer-kicker"><FileText size={14} /> QUOTATION DETAIL</p><h1>{quote.quoteNumber}</h1><span>{quotationStatus(quote.status)} · valid until {quote.validUntil ? new Date(quote.validUntil).toLocaleDateString("en-IN") : "—"}</span></div><Link className="customer-secondary" href="/account/quotations">Back to quotations</Link></div><DetailFields values={[["Project", quote.customer.projectName], ["Project location", quote.customer.projectLocation], ["Quotation date", new Date(quote.createdAt).toLocaleDateString("en-IN")], ["Customer", quote.customer.company || quote.customer.fullName]]} /><div className="customer-quote-lines"><div><span>Product</span><span>Supply quantity</span><span>Rate</span><span>Amount</span></div>{quote.items.map((item, index) => <article className={item.customBuiltUp ? "customer-built-up-line" : ""} key={`${item.variantId}-${index}`}><span><strong>{item.productName}</strong><small>{item.configuration}</small>{item.customBuiltUp && <small>Grouped basic total: {money(item.amount)}</small>}</span>{item.customBuiltUp ? <CustomerBuiltUpCommercialCells quotationItem={item} /> : <><span>{item.technicalQuantity}</span><span>{money(item.rate)}<small>{item.rateUnit}</small></span><strong>{money(item.amount)}</strong></>}</article>)}</div><div className="customer-commercial-summary"><span>Basic material value <b>{money(quote.subtotal)}</b></span><span>GST ({quote.gstRate}%) <b>{money(quote.gstAmount)}</b></span><span>Transportation <b>At Actual</b></span><strong>Total <b>{money(quote.total)}</b></strong></div><section className="customer-detail-note"><strong>Commercial terms</strong><p>{quote.paymentTerms} Transportation at actual. Prices are basic ex-works plus applicable GST. Offer validity and standard packing are shown in the quotation PDF.</p></section>{message && <p className="customer-note">{message}</p>}<div className="customer-auth-actions"><button className="customer-primary" onClick={download}><Download size={16} /> Download PDF</button>{!restricted && <button className="customer-secondary" onClick={() => setRevisionOpen((open) => !open)}>Request revision</button>}<Link className="customer-secondary" href={`/generate-quotation?similar=${quote.id}`}>Create similar quote</Link><a className="customer-secondary" href={whatsappContactHref(`quotation ${quote.quoteNumber}`)} target="_blank" rel="noreferrer"><MessageCircle size={16} /> Contact RAC</a></div>{revisionOpen && <form className="customer-form customer-form-grid customer-revision-form" onSubmit={requestRevision}><p className="customer-kicker customer-full">REQUEST A QUOTATION REVISION</p><label className="customer-full">Reason for revision<textarea required name="reason" rows={3} placeholder="Describe why this quotation needs revision." /></label><label>Required change<input name="requiredChange" placeholder="Specification or scope" /></label><label>Quantity change<input name="quantityChange" placeholder="Updated quantity" /></label><label>Product change<input name="productChange" placeholder="Alternative product" /></label><label>Delivery change<input name="deliveryChange" placeholder="Updated delivery requirement" /></label><label className="customer-full">Additional notes<textarea name="additionalNotes" rows={3} /></label><div className="customer-auth-actions customer-full"><button type="button" className="customer-secondary" onClick={() => setRevisionOpen(false)}>Cancel</button><button className="customer-primary" disabled={busy}>{busy ? "Submitting…" : "Send revision request"}<ArrowRight size={16} /></button></div></form>}</section></AccountFrame>;
}

export function CustomerProjectsPage() {
  const { portal, error } = useActivePortal(); const [creating, setCreating] = useState(false); const [message, setMessage] = useState(""); const [busy, setBusy] = useState(false); if (!portal) return <AccountLoading error={error} />;
  const createProject = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); setBusy(true); setMessage(""); try { const response = await customerFetch("/api/customer-portal/projects", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ title: form.get("title"), location: form.get("location"), application: form.get("application"), deliveryLocation: form.get("deliveryLocation"), expectedRequirementDate: form.get("expectedRequirementDate"), notes: form.get("notes") }) }); const result = await response.json() as PortalResponse; if (!response.ok) throw new Error(result.message || "Could not create the project."); window.location.reload(); } catch (issue) { setMessage(issue instanceof Error ? issue.message : "Could not create the project."); } finally { setBusy(false); } };
  return <AccountFrame><PortalNav active="projects" /><section className="customer-account-card"><div className="customer-card-title"><div><p className="customer-kicker"><FolderKanban size={14} /> PROJECT WORKSPACE</p><h1>My projects</h1></div><button className="customer-primary" onClick={() => setCreating((open) => !open)}><Plus size={16} /> Create project</button></div>{creating && <form className="customer-form customer-form-grid customer-revision-form" onSubmit={createProject}><label>Project name<input required name="title" /></label><label>Project location<input name="location" /></label><label>Industry / application<input name="application" /></label><label>Delivery location<input name="deliveryLocation" /></label><label>Expected requirement date<input name="expectedRequirementDate" type="date" /></label><label className="customer-full">Notes<textarea name="notes" rows={3} /></label>{message && <p className="customer-error customer-full">{message}</p>}<div className="customer-auth-actions customer-full"><button type="button" className="customer-secondary" onClick={() => setCreating(false)}>Cancel</button><button className="customer-primary" disabled={busy}>{busy ? "Creating…" : "Create project"}</button></div></form>}<div className="customer-list customer-list-expanded">{portal.projects?.length ? portal.projects.map((project) => <article key={project.id}><div><strong>{project.title}</strong><span>{project.location || "Location to be confirmed"} · {project.requirement || "General insulation"}</span><small>{project.projectStatus.replaceAll("_", " ")}</small></div><Link href={`/account/projects/${project.id}`}>View <ArrowRight size={14} /></Link></article>) : <div className="customer-empty-state"><FolderKanban size={26} /><p>Create a project to group enquiries and quotations.</p><button className="customer-primary" onClick={() => setCreating(true)}>Create project</button></div>}</div></section></AccountFrame>;
}

export function CustomerProjectDetailPage({ id }: { id: string }) { const { portal, error: accessError } = useActivePortal({ allowRestricted: true }); const { data, error } = usePortalDetail(`/api/customer-portal/projects/${id}`); if (!portal || !data?.project) return <DetailLoading error={accessError || error} />; const project = data.project; const restricted = portal.account?.status !== "active"; return <AccountFrame><PortalNav active="projects" restricted={restricted} /><section className="customer-account-card customer-detail-card"><div className="customer-card-title"><div><p className="customer-kicker"><FolderKanban size={14} /> PROJECT DETAIL</p><h1>{project.title}</h1><span>{project.projectStatus.replaceAll("_", " ")}</span></div><Link className="customer-secondary" href="/account/projects">Back to projects</Link></div><DetailFields values={[["Location", project.location], ["Application", project.requirement], ["Delivery location", project.solution], ["Expected requirement date", project.expectedDeliveryDate]]} /><section className="customer-detail-note"><strong>Notes</strong><p>{project.scope || "No project notes yet."}</p></section><section className="customer-detail-note"><strong>Linked activity</strong><p>{data.linked?.enquiries || 0} enquiries · {data.linked?.quotations || 0} quotations</p></section>{!restricted && <div className="customer-auth-actions"><Link className="customer-primary" href={`/?quote=1&project=${encodeURIComponent(project.title)}`}>Submit enquiry for this project</Link><Link className="customer-secondary" href={`/generate-quotation?project=${encodeURIComponent(project.id)}`}>Generate quotation</Link></div>}</section></AccountFrame>; }

export function CustomerDocumentsPage() { const { portal, error } = useActivePortal(); const [filter, setFilter] = useState("all"); if (!portal) return <AccountLoading error={error} />; const documents = (portal.documents || []).filter((item) => filter === "all" || item.documentType === filter); return <AccountFrame><PortalNav active="documents" /><section className="customer-account-card"><div className="customer-card-title"><div><p className="customer-kicker"><FileText size={14} /> DOCUMENT LIBRARY</p><h1>Documents</h1></div></div><div className="customer-filter-row">{[["all", "All"], ["brochure", "Brochures"], ["datasheet", "Datasheets"]].map(([value, label]) => <button className={filter === value ? "active" : ""} onClick={() => setFilter(value)} key={value}>{label}</button>)}</div><div className="customer-list customer-list-expanded">{documents.length ? documents.map((document) => <article key={document.id}><div><strong>{document.title}</strong><span>{document.documentType.replaceAll("_", " ")} · {document.materialFamily || "RAC Insutech"}</span><small>Version {document.version || "current"}</small></div><a className="customer-row-link" href={document.fileUrl}>Open <Download size={14} /></a></article>) : <div className="customer-empty-state"><FileText size={26} /><p>No documents match this filter.</p></div>}</div></section></AccountFrame>; }

export function CustomerSupportPage() { const { portal, error } = useActivePortal({ allowRestricted: true }); if (!portal) return <AccountLoading error={error} />; const restricted = portal.account?.status !== "active"; return <AccountFrame><PortalNav active="support" restricted={restricted} /><section className="customer-account-card customer-support-card"><p className="customer-kicker"><Headphones size={14} /> RAC SUPPORT</p><h1>How can RAC help?</h1><p>For technical guidance, quotation questions or account assistance, contact the RAC Insutech team with the relevant enquiry or quotation number.</p><div className="customer-support-actions"><a className="customer-primary" href={whatsappContactHref("customer portal support")} target="_blank" rel="noreferrer"><MessageCircle size={17} /> WhatsApp RAC</a><a className="customer-secondary" href="tel:+919130958594">Call +91 91309 58594</a><a className="customer-secondary" href="mailto:racinsutech@gmail.com">Email RAC</a></div><section className="customer-detail-note"><strong>Account access</strong><p>{restricted ? "Your account currently has limited access. RAC can help you with approval or access questions." : "Include your quotation or enquiry reference to help RAC respond quickly."}</p></section></section></AccountFrame>; }

export function AuthCallbackPage() {
  const router = useRouter(); const params = useSearchParams(); const intent = params.get("intent") || ""; const [message, setMessage] = useState("Confirming your verified account…");
  useEffect(() => { let alive = true; (async () => { try { await continueByStatus(router, intent); } catch (error) { if (alive) setMessage(error instanceof Error ? error.message : "Your email was verified. Please sign in to continue."); } })(); return () => { alive = false; }; }, [intent, router]);
  return <AuthCard><div className="customer-kicker"><MailCheck size={15} /> EMAIL CONFIRMATION</div><h1>Finishing account setup</h1><p>{message}</p><Link className="customer-secondary" href={intentUrl("/account/sign-in", intent)}>Go to sign in</Link></AuthCard>;
}
